sys_script.script:
(function executeRule(current, previous) {
    var newStatus = current.getValue('status');
    var oldStatus = previous.getValue('status');

    // Only run when status changes to 'completed'
    if (newStatus !== 'completed' || oldStatus === 'completed') {
        return;
    }

    var tyreTypeId = current.getValue('tyre_type');
    if (!tyreTypeId) {
        return;
    }

    var quantity = parseInt(current.getValue('quantity'), 10);
    if (isNaN(quantity) || quantity <= 0) {
        return;
    }

    var tyreGr = new GlideRecord('x_1527007_tyre_r_1_tyre');
    if (tyreGr.get(tyreTypeId)) {
        var currentStock = parseInt(tyreGr.getValue('stock_quantity'), 10) || 0;
        var newStock = currentStock - quantity;
        tyreGr.setValue('stock_quantity', newStock < 0 ? 0 : newStock);
        tyreGr.update();

        if (newStock < 0) {
            gs.addInfoMessage('Warning: Tyre stock for "' + tyreGr.getValue('name') + '" is now depleted.');
        }
    }
})(current, previous);
